            data = request.get_json()
            if not data:
                raise BadRequest('No JSON in request')

            self.validate_request(data)
            result = self.execute_business_logic(data)
            response = self.render_template('template.html', result)
            self.cache_response(response, request.path)
            return self.api_response(result)

        except Exception as e:
            self.handle_error(e)
            return self.api_response({'error': str(e)}, 500)
```

